  "lines": [
    {
      "id": "progress.multi_exercise",
      "tiers": [
        {
          "id": "progress.multi_exercise:t1",
          "title": "Дуэт без фальстарта",
          "phrase": "В 2 разных упражнениях у тебя уже есть подтверждённые улучшения. Прогресс собрал дуэт — железо, вступай по очереди!",
          "imagePrompt": "A small octopus conductor raises a baton before a kettlebell and a dumbbell standing like a musical duo. Both pieces of equipment lean toward the cue, while a tiny closed tea flask waits beside the podium.",
          "fishMarkup": "[warm] В 2 разных упражнениях у тебя уже есть подтверждённые улучшения. [playful] Прогресс собрал дуэт — железо, вступай по очереди!",
          "audioText": "В 2 разных упражнениях у тебя уже есть подтверждённые улучшения. Прогресс собрал дуэт — железо, вступай по очереди!"
        },
        {
          "id": "progress.multi_exercise:t2",
          "title": "Квартет набрал ход",
          "phrase": "Ты собрал подтверждённые улучшения в 4 разных упражнениях. У прогресса уже квартет: лень в состав не прошла.",
          "imagePrompt": "The octopus conductor leads a quartet of a kettlebell, dumbbell, rowing handle and coiled battle rope. Several arms cue separate entrances while another steadies a teacup that has become impossible to sip.",
          "fishMarkup": "[confident] Ты собрал подтверждённые улучшения в 4 разных упражнениях. [playful] У прогресса уже квартет: лень в состав не прошла.",
          "audioText": "Ты собрал подтверждённые улучшения в 4 разных упражнениях. У прогресса уже квартет: лень в состав не прошла."
        },
        {
          "id": "progress.multi_exercise:t3",
          "title": "Восемь партий прогресса",
          "phrase": "Подтверждённые улучшения в 8 разных упражнениях — ты собрал целый оркестр! Дирижёр-осьминог занят: чай ему подаёт стажёр.",
          "imagePrompt": "The octopus conducts eight distinct exercise implements arranged as a compact orchestra, every arm busy giving a cue. A tiny shrimp intern climbs a step stool to serve tea directly to the conductor's delighted mouth.",
          "fishMarkup": "[triumphant] Подтверждённые улучшения в 8 разных упражнениях — ты собрал <emphasis>целый оркестр!</emphasis> [playful] Дирижёр-осьминог занят: <slow>чай ему подаёт стажёр.</slow>",
          "audioText": "Подтверждённые улучшения в 8 разных упражнениях — ты собрал целый оркестр! Дирижёр-осьминог занят: чай ему подаёт стажёр."
        }
      ]
    },
    {
      "id": "progress.after_month",
      "tiers": [
        {
          "id": "progress.after_month:t1",
          "title": "Время предъявить разницу",
          "phrase": "Ты улучшил результат в 1 упражнении относительно исходного замера давностью не меньше 28 дней. Улитка-архивариус довольно шуршит папкой.",
          "imagePrompt": "A bespectacled snail archivist opens a weathered folder on a low desk. Inside, a curled old picture and a fresh picture show the same kettlebell, with the newer result represented by a taller plain bar.",
          "fishMarkup": "[warm] Ты улучшил результат в 1 упражнении относительно исходного замера давностью не меньше 28 дней. [playful] Улитка-архивариус довольно шуршит папкой.",
          "audioText": "Ты улучшил результат в 1 упражнении относительно исходного замера давностью не меньше 28 дней. Улитка-архивариус довольно шуршит папкой."
        },
        {
          "id": "progress.after_month:t2",
          "title": "Архив пошёл на выезд",
          "phrase": "В 3 упражнениях ты превзошёл исходные результаты давностью не меньше 28 дней. Улитка-архивариус уже выкатила целую тележку доказательств.",
          "imagePrompt": "The snail archivist pushes a trolley carrying three open folders, each pairing a curled old equipment picture with a fresh one. Its shell supports a foldout sorting desk, and loose blank dividers nearly engulf the determined clerk.",
          "fishMarkup": "[confident] В 3 упражнениях ты превзошёл исходные результаты давностью не меньше 28 дней. [playful] Улитка-архивариус уже выкатила целую тележку доказательств.",
          "audioText": "В 3 упражнениях ты превзошёл исходные результаты давностью не меньше 28 дней. Улитка-архивариус уже выкатила целую тележку доказательств."
        },
        {
          "id": "progress.after_month:t3",
          "title": "Прошлое водит экскурсии",
          "phrase": "В 6 упражнениях ты превзошёл исходные результаты давностью не меньше 28 дней. Архив стал музеем — прежние результаты теперь водят экскурсии.",
          "imagePrompt": "The snail's shell has unfolded into a miniature museum with six paired equipment exhibits. A retired kettlebell acts as the tour guide, pointing at its own old portrait while the snail ceremoniously pulls open the entrance curtains.",
          "fishMarkup": "[triumphant] В 6 упражнениях ты превзошёл исходные результаты давностью не меньше 28 дней. [playful] Архив стал музеем — <slow>прежние результаты теперь водят экскурсии.</slow>",
          "audioText": "В 6 упражнениях ты превзошёл исходные результаты давностью не меньше 28 дней. Архив стал музеем — прежние результаты теперь водят экскурсии."
        }
      ]
    }
  ]
}
